dtsPropsFor.Button:
/** primary (default) | secondary | ghost | accept (sage, saying yes) | danger (rose, decline or remove) */
  variant?: "primary" | "secondary" | "ghost" | "accept" | "danger";
  size?: "sm" | "md" | "lg";
  disabled?: boolean;
  /** Defaults to "button". Pass "submit" for a real form submit. */
  type?: "button" | "submit" | "reset";
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  "aria-label"?: string;
  className?: string;
  id?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;

dtsPropsFor.Chip:
/** Filled with the accent when true; rendered as aria-pressed. */
  selected?: boolean;
  /** Optional leading emoji, hidden from assistive tech. */
  emoji?: string;
  disabled?: boolean;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  "aria-label"?: string;
  className?: string;
  id?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;

dtsPropsFor.Avatar:
/** Drives the initials and the fallback hue. */
  name: string;
  /** Pins the hue to something other than the name, such as an id. */
  seed?: string;
  /** Photo URL. Omit for deterministic initials. */
  src?: string | null;
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /** White ring, for avatars on colored surfaces. */
  ring?: boolean;
  /** Live-signal ring (sage) and emoji badge. Omit or pass null for no signal. */
  signal?: { emoji: string; label: string } | null;
  className?: string;

dtsPropsFor.PlanCard:
title: string;
/** One of the six plan tokens; use planColor(i) to rotate by position. */
color?: "pink" | "purple" | "blue" | "jade" | "orange" | "magenta";
imageUrl?: string | null;
attendees?: { name: string; src?: string | null }[];
/** The sentence under the cluster, such as "You and 3 others". */
attendeesLabel?: string;
when?: string;
dateLabel?: string;
where?: string;
distance?: string;
/** Small uppercase pill, such as "Deciding" or "Confirmed". */
status?: string;
/** Wraps the card in a link when set. */
href?: string;
/** Usually two Buttons: accept plus secondary. Full variant only. */
actions?: React.ReactNode;
variant?: "full" | "compact" | "tile";
className?: string;
